import java.util.*; public class Solution {public static int[][] merge(int[][] a){if(a==null)throw new IllegalArgumentException();int[][] b=new int[a.length][];for(int i=0;i<a.length;i++){if(a[i]==null||a[i].length!=2||a[i][0]>=a[i][1])throw new IllegalArgumentException();b[i]=a[i].clone();}Arrays.sort(b,(x,y)->Integer.compare(x[0],y[0]));List<int[]> out=new ArrayList<>();for(int[] p:b){if(out.isEmpty()||p[0]>=out.get(out.size()-1)[1])out.add(p);else out.get(out.size()-1)[1]=Math.max(out.get(out.size()-1)[1],p[1]);}return out.toArray(new int[0][]);}}
